}

/* Responsive Design */
@media (max-width: 1024px) {
    .login-container {
        grid-template-columns: 1fr;
        gap: 40px;
    }
    
    .login-hero-content {
        grid-template-columns: 1fr;
        gap: 40px;
        text-align: center;
    }
}

@media (max-width: 768px) {
    .login-hero {
        padding: 60px 0;
    }
    
    .login-hero-text h1 {
        font-size: 2.5rem;
    }
    
    .login-benefits {
        flex-direction: column;
        gap: 20px;
    }
    
    .login-form-wrapper {
        padding: 30px 20px;
    }
    
    .floating-elements {
        height: 300px;
    }
}

@media (max-width: 480px) {
    .login-hero-text h1 {
        font-size: 2rem;
    }
    
    .login-form-wrapper {
        padding: 20px 15px;
    }
    
    .form-options {
        flex-direction: column;
        gap: 15px;
        align-items: flex-start;
    }
}


