    display: flex;
    align-items: center;
    gap: 12px;
    width: 100%;
    overflow: visible;
    z-index: 2;
}

.scroll-btn {
    background: #28282838;
    border: 2px solid #bfbfbf;
    color: #bfbfbf;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.3s ease;
    flex-shrink: 0;
    z-index: 2;
}

.scroll-btn:hover {
    background: #FF5E00;
    color: white;
    border-color: #FF5E00;
    transform: scale(1.1);
}

.categories-scroll-wrapper {
    flex: 1;
    overflow-x: auto;
    overflow-y: hidden;
    scroll-behavior: smooth;
    scrollbar-width: none;
    -ms-overflow-style: none;
    padding: 10px 0;
    padding-left: 0;
    padding-right: 20px; /* space for right arrow */
    display: flex;
    gap: 13px;
    width: 100%;
    position: relative;
}

/* spacer at end so last item is fully visible */
.categories-scroll-wrapper::after { 
    content: ''; 
    flex: 0 0 60px; 
    min-width: 60px;
}

.categories-scroll-wrapper::-webkit-scrollbar {
    display: none;
}

.category-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 20px 15px;
    background: #28282838;
    border-radius: 12px;
    min-width: 120px;
    flex-shrink: 0;
    text-align: center;
    transition: all 0.3s ease;
    cursor: pointer;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
    border: 2px solid #ff5e00e0;
}

.category-item:hover {
    transform: translateY(-5px);
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.15);
    border-color: #FF5E00;
}

.category-icon {
    width: 35px;
    height: 35px;
    background: linear-gradient(135deg, #FF5E00, #FF8C42);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 8px;
    transition: all 0.3s ease;
}

.category-icon i {
    font-size: 1rem;
    color: white;
}

.category-item:hover .category-icon {
    background: linear-gradient(135deg, #00B2FF, #FF5E00);
    transform: scale(1.1);
}

.category-name {
    font-size: 0.8rem;
    font-weight: 600;
    color: #bfbfbf;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    line-height: 1.2;
}

/* Responsive Design for Top Categories */
@media (max-width: 768px) {
    .top-categories {
        padding: 30px 0;
    }
    
    .categories-title {
        font-size: 1.5rem;
        margin-bottom: 20px;
    }
    
    .scroll-btn {
        width: 35px;
        height: 35px;
    }
    
    .category-item {
        min-width: 100px;
        padding: 15px 10px;
        margin-right: 10px;
    }
    /* leave space for right arrow button on mobile */
    .categories-scroll-wrapper { padding-right: 60px; }
    
    .category-icon {
        width: 30px;
        height: 30px;
    }
    
    .category-icon i {
        font-size: 0.9rem;
    }
    
    .category-name {
        font-size: 0.7rem;
    }
}

@media (max-width: 480px) {
    .categories-scroll-container {
        gap: 10px;
    }
    
    .scroll-btn {
        width: 30px;
        height: 30px;
    }
    
    .category-item {
        min-width: 80px;
        padding: 12px 8px;
        margin-right: 8px;
    }
    
    .category-icon {
        width: 25px;
        height: 25px;
    }
    
    .category-icon i {
        font-size: 0.8rem;
    }
    
    .category-name {
        font-size: 0.65rem;
    }
}

