    transition: all 0.3s ease;
    border: 2px solid rgba(255, 255, 255, 0.6);
}

.banner-dot.active {
    background: white;
    border-color: white;
    transform: scale(1.2);
}

.banner-dot:hover {
    background: rgba(255, 255, 255, 0.7);
    transform: scale(1.1);
}

