    gap: 10px;
}

.offers-prev,
.offers-next {
    background: rgba(255, 255, 255, 0.1);
    border: 2px solid rgba(255, 94, 0, 0.3);
    color: #FF5E00;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.3s ease;
    backdrop-filter: blur(10px);
}

.offers-prev:hover,
.offers-next:hover {
    background: #FF5E00;
    color: white;
    transform: scale(1.1);
    box-shadow: 0 5px 15px rgba(255, 94, 0, 0.3);
}

.offers-carousel {
    overflow: hidden;
    position: relative;
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 20px;
    display: flex;
    justify-content: center;
}

.offers-slider {
    display: flex;
    gap: 12px;
    transition: transform 0.5s ease;
    width: max-content;
    max-width: 1200px;
}
.offers-slider::after { content: ''; flex: 0 0 60px; }

.offer-card {
    background: linear-gradient(145deg, rgba(255, 255, 255, 0.1) 0%, rgba(255, 255, 255, 0.05) 100%);
    border: 2px solid rgba(255, 94, 0, 0.2);
    border-radius: 20px;
    padding: 20px;
    width: 280px;
    flex-shrink: 0;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    cursor: pointer;
    position: relative;
    overflow: hidden;
    backdrop-filter: blur(10px);
}

.offer-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255, 94, 0, 0.1), transparent);
    transition: left 0.5s ease;
}

.offer-card:hover::before {
    left: 100%;
}

.offer-card:hover {
    transform: translateY(-10px);
    border-color: #FF5E00;
    box-shadow: 0 20px 40px rgba(255, 94, 0, 0.2);
    background: linear-gradient(145deg, rgba(255, 94, 0, 0.1) 0%, rgba(0, 178, 255, 0.05) 100%);
}

.offer-image {
    position: relative;
    width: 100%;
    height: 200px;
    border-radius: 15px;
    overflow: hidden;
    margin-bottom: 15px;
    background: linear-gradient(145deg, #f8f9fa 0%, #e9ecef 100%);
}

.offer-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.3s ease;
}

.offer-card:hover .offer-image img {
    transform: scale(1.05);
}

.discount-badge {
    position: absolute;
    top: 10px;
    right: 10px;
    background: linear-gradient(45deg, #FF5E00, #FF8C42);
    color: white;
    padding: 5px 10px;
    border-radius: 15px;
    font-size: 0.8rem;
    font-weight: 700;
    z-index: 2;
    box-shadow: 0 2px 8px rgba(255, 94, 0, 0.3);
}

.offer-content {
    text-align: center;
}

.offer-title {
    font-size: 1rem;
    font-weight: 600;
    margin-bottom: 8px;
    color: #c7c7c7;
    line-height: 1.4;
    text-transform: none;
    letter-spacing: 0.5px;
}

.offer-category {
    font-size: 0.8rem;
    color: #666;
    margin-bottom: 12px;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.offer-price {
    margin-bottom: 15px;
}

.original-price {
    font-size: 0.9rem;
    color: #999;
    text-decoration: line-through;
    margin-right: 8px;
}

.discounted-price {
    font-size: 1.3rem;
    font-weight: 700;
    color: #FF5E00;
    text-shadow: 0 2px 4px rgba(255, 94, 0, 0.2);
}

.offer-btn {
    width: 100%;
    background: linear-gradient(45deg, #FF5E00, #FF8C42);
    color: white;
    border: none;
    padding: 12px 20px;
    border-radius: 8px;
    font-weight: 700;
    font-size: 0.9rem;
    cursor: pointer;
    transition: all 0.3s ease;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    box-shadow: 0 4px 15px rgba(255, 94, 0, 0.3);
}

.offer-btn:hover {
    background: linear-gradient(45deg, #FF8C42, #FF5E00);
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(255, 94, 0, 0.4);
}

/* Responsive Design for Special Offers */
@media (max-width: 1200px) {
    .offer-card {
        width: 250px;
    }
}

@media (max-width: 768px) {
    .special-offers {
        padding: 40px 0;
