}

.blog-carousel {
    overflow: hidden;
    position: relative;
    max-width: 1400px;
    margin: 0 auto;
    padding: 30px 20px;
}

.blog-slider {
    display: flex;
    gap: 30px;
    transition: transform 0.5s ease;
    width: max-content;
}
.blog-slider::after { content: ''; flex: 0 0 60px; }

.blog-card {
    background: linear-gradient(145deg, rgba(255, 255, 255, 0.1) 0%, rgba(255, 255, 255, 0.05) 100%);
    border: 2px solid rgba(255, 94, 0, 0.2);
    border-radius: 20px;
    padding: 0;
    width: 300px;
