    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    cursor: pointer;
    position: relative;
    overflow: hidden;
    backdrop-filter: blur(10px);
}

.blog-card:hover {
    transform: translateY(-10px);
    border-color: #FF5E00;
    box-shadow: 0 20px 40px rgba(255, 94, 0, 0.2);
    background: linear-gradient(145deg, rgba(255, 94, 0, 0.1) 0%, rgba(0, 178, 255, 0.05) 100%);
}

.blog-image {
    position: relative;
    width: 100%;
    height: 200px;
    overflow: hidden;
}

.blog-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.3s ease;
}

.blog-card:hover .blog-image img {
    transform: scale(1.05);
}

.blog-category {
    position: absolute;
    top: 15px;
    left: 15px;
    background: linear-gradient(45deg, #FF5E00, #FF8C42);
    color: white;
    padding: 5px 12px;
    border-radius: 15px;
    font-size: 0.8rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    z-index: 2;
}

.blog-content {
    padding: 25px;
}

.blog-post-title {
    font-size: 1.2rem;
    font-weight: 700;
    margin-bottom: 12px;
    color: #ececec;
    line-height: 1.4;
    text-transform: none;
    letter-spacing: 0.5px;
}

.blog-excerpt {
    font-size: 0.9rem;
    color: #e7e5e5;
    margin-bottom: 15px;
    line-height: 1.6;
}

.blog-meta {
    display: flex;
    justify-content: space-between;
    margin-bottom: 15px;
    font-size: 0.8rem;
    color: #999;
}

.blog-date,
.blog-author {
    font-weight: 500;
}

.blog-read-more {
    display: inline-block;
    color: #FF5E00;
    text-decoration: none;
    font-weight: 600;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    transition: all 0.3s ease;
    position: relative;
}

.blog-read-more::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 0;
    width: 0;
    height: 2px;
    background: #FF5E00;
    transition: width 0.3s ease;
}

.blog-read-more:hover::after {
    width: 100%;
}

.blog-read-more:hover {
    color: #FF8C42;
