    }
    
    .newsletter-form {
        flex-direction: column;
        gap: 15px;
    }
}

@media (max-width: 768px) {
    .footer-widgets {
        padding: 60px 0 40px;
    }
    
    .footer-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
