    animation: shimmer 3s infinite;
}

@keyframes shimmer {
    0% { transform: translateX(-100%); }
    100% { transform: translateX(100%); }
}

.shop-banner-content {
    text-align: center;
    color: white;
    z-index: 2;
    position: relative;
}

.shop-banner h2 {
    font-size: 2.2rem;
    font-weight: 900;
    margin-bottom: 8px;
    text-shadow: 0 4px 8px rgba(0, 0, 0, 0.3);
}

.shop-banner p {
    font-size: 1.1rem;
    opacity: 0.9;
    font-weight: 500;
}

.shop-banner .banner-icon {
    font-size: 3rem;
    margin-bottom: 10px;
    opacity: 0.8;
}

/* ==========================================
   Shop Product Detail Panel
   ========================================== */
.shop-product-detail {
    display: none;
    margin-bottom: 40px;
}

.shop-product-detail.active {
    display: block;
}

.shop-product-detail-inner {
    position: relative;
    padding: 32px;
    border-radius: 24px;
    background: linear-gradient(145deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.03));
    border: 1px solid rgba(255, 255, 255, 0.12);
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.35);
    backdrop-filter: blur(18px);
}

.shop-product-detail-close {
    position: absolute;
    top: 16px;
    right: 16px;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    border: none;
    background: rgba(255, 255, 255, 0.12);
    color: #ffffff;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.3s ease;
}

.shop-product-detail-close:hover {
    background: rgba(255, 94, 0, 0.85);
    transform: scale(1.05);
}

.shop-detail-layout {
    display: grid;
    grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr);
    gap: 32px;
    align-items: stretch;
}

@media (max-width: 1024px) {
    .shop-detail-layout {
        grid-template-columns: 1fr;
    }
}

.shop-detail-gallery {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.shop-detail-main {
    background: linear-gradient(135deg, #0d0d0d 0%, #1b1b1b 100%);
    border-radius: 18px;
    overflow: hidden;
    min-height: 300px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.shop-detail-main img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.shop-detail-thumbs {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
}

.shop-detail-thumb {
    width: 72px;
    height: 72px;
    border-radius: 12px;
    border: none;
    padding: 4px;
    background: rgba(255, 255, 255, 0.1);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.3s ease;
}

.shop-detail-thumb img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 8px;
}

.shop-detail-thumb:hover,
.shop-detail-thumb.active {
    background: linear-gradient(135deg, #FF5E00, #FF8C00);
}

.shop-detail-info h2 {
    font-size: 1.8rem;
    font-weight: 700;
    color: #ffffff;
    margin-bottom: 12px;
}

.shop-detail-breadcrumb {
    font-size: 0.9rem;
    color: rgba(255, 255, 255, 0.6);
    margin-bottom: 12px;
}

.shop-detail-breadcrumb a {
    color: rgba(255, 255, 255, 0.7);
    text-decoration: none;
}

.shop-detail-breadcrumb a:hover {
    color: #FF8C00;
}

.shop-detail-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    align-items: center;
    margin-bottom: 16px;
}

.shop-detail-price {
    font-size: 1.6rem;
    font-weight: 700;
    color: #FF8C00;
}

.shop-detail-original {
    font-size: 1rem;
    text-decoration: line-through;
    color: rgba(255, 255, 255, 0.45);
}

.shop-detail-discount {
    font-size: 0.85rem;
    font-weight: 600;
    color: #00E5FF;
    background: rgba(0, 229, 255, 0.16);
    padding: 4px 10px;
    border-radius: 999px;
}

.shop-detail-rating {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 0.95rem;
    color: rgba(255, 255, 255, 0.78);
}

.shop-detail-rating .fas {
    color: #FFD700;
}

.shop-detail-description {
    margin-bottom: 18px;
    color: rgba(255, 255, 255, 0.75);
    line-height: 1.6;
}

.shop-detail-features {
    list-style: none;
    padding: 0;
    margin: 0 0 18px 0;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 12px;
}

.shop-detail-features li {
    display: flex;
    gap: 10px;
    align-items: center;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.09);
    border-radius: 12px;
    padding: 10px 14px;
    font-size: 0.9rem;
    color: rgba(255, 255, 255, 0.78);
}

.shop-detail-features i {
    color: #FF8C00;
}

.shop-detail-specs {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 12px;
    margin-bottom: 24px;
}

.shop-detail-spec {
    background: rgba(255, 255, 255, 0.05);
    border-radius: 12px;
    padding: 12px 16px;
    border: 1px solid rgba(255, 255, 255, 0.07);
}

.shop-detail-spec .spec-label {
    display: block;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: rgba(255, 255, 255, 0.6);
    margin-bottom: 6px;
}

.shop-detail-spec .spec-value {
    font-size: 0.95rem;
    color: rgba(255, 255, 255, 0.85);
    font-weight: 600;
}

.shop-detail-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 16px;
    align-items: center;
}

.shop-detail-add-cart,
.shop-detail-view-product {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 12px 24px;
    border-radius: 999px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    cursor: pointer;
    transition: all 0.3s ease;
    border: none;
    text-decoration: none;
}

.shop-detail-add-cart {
    background: linear-gradient(135deg, #FF5E00, #FF8C00);
    color: #ffffff;
}

.shop-detail-add-cart:hover {
    transform: translateY(-2px);
    box-shadow: 0 12px 24px rgba(255, 94, 0, 0.35);
}

.shop-detail-view-product {
    background: transparent;
    color: rgba(255, 255, 255, 0.8);
    border: 1px solid rgba(255, 255, 255, 0.25);
}

.shop-detail-view-product:hover {
    color: #00E5FF;
    border-color: #00E5FF;
    transform: translateY(-2px);
}

@media (max-width: 768px) {
    .shop-product-detail-inner {
        padding: 24px;
    }

    .shop-detail-actions {
        flex-direction: column;
        align-items: stretch;
    }

    .shop-detail-add-cart,
    .shop-detail-view-product {
        justify-content: center;
        width: 100%;
    }
}

.shop-product-card.selected,
.shop-products-grid .shop-product-card.selected {
    border-color: rgba(255, 94, 0, 0.75) !important;
    box-shadow: 0 0 0 2px rgba(255, 94, 0, 0.35), 0 18px 36px rgba(0, 0, 0, 0.4) !important;
}

/* Category hero alignment */
.category-hero {
    background: linear-gradient(135deg, rgba(255, 94, 0, 0.08), rgba(0, 178, 255, 0.08));
    padding: 40px 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.category-header-content {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 32px;
    flex-wrap: wrap;
}

.category-header-copy {
    max-width: 640px;
}

.category-header-meta {
    display: flex;
    gap: 16px;
    flex-wrap: wrap;
}

.category-meta-item {
    min-width: 140px;
    padding: 16px 20px;
    border-radius: 18px;
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid rgba(255, 255, 255, 0.12);
    text-align: center;
}

.category-meta-value {
    display: block;
    font-size: 1.6rem;
    font-weight: 700;
    color: #ffffff;
}

.category-meta-label {
    display: block;
    font-size: 0.85rem;
    color: rgba(255, 255, 255, 0.65);
    letter-spacing: 0.5px;
    text-transform: uppercase;
}

@media (max-width: 768px) {
    .category-header-content {
        gap: 24px;
    }

    .category-meta-item {
        min-width: calc(50% - 12px);
    }
}

.shop-empty-state {
    text-align: center;
    padding: 80px 20px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 20px;
    color: rgba(255, 255, 255, 0.75);
}

.shop-empty-state h3 {
    font-size: 1.6rem;
    margin-bottom: 12px;
    color: #ffffff;
}

.shop-empty-state p {
    margin: 0 0 20px;
}

.shop-empty-state a {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 12px 24px;
    border-radius: 999px;
    background: linear-gradient(135deg, #FF5E00, #FF8C00);
    color: #ffffff;
    text-decoration: none;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@400;700;900&family=Rajdhani:wght@300;400;500;700&display=swap');

@import url('https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css');

