    margin: 0 auto;
    padding: 0 20px;
}

.category-card {
    background: rgba(255, 255, 255, 0.02);
    border: 1px solid rgba(255, 94, 0, 0.2);
    border-radius: 20px;
    padding: 40px 30px;
    text-align: center;
