/* Newsletter Section */
.newsletter {
    padding: 20px 0;
    background: linear-gradient(135deg, rgba(255, 94, 0, 0.1) 0%, rgba(0, 178, 255, 0.1) 100%);
    border-top: 1px solid rgba(255, 94, 0, 0.2);
    border-bottom: 1px solid rgba(255, 94, 0, 0.2);
}

.newsletter-content {
    text-align: center;
    max-width: 800px;
    margin: 0 auto;
    padding: 0 20px;
}

.newsletter h2 {
    font-size: 2.5rem;
    font-weight: 700;
    margin-bottom: 20px;
    color: #ffffff;
    text-transform: uppercase;
    letter-spacing: 2px;
}

.newsletter p {
    font-size: 1.2rem;
    color: rgba(255, 255, 255, 0.8);
    margin-bottom: 40px;
}

.newsletter-form {
    display: flex;
    gap: 15px;
    max-width: 800px;
    margin: 0 auto;
}

.newsletter-form input {
    flex: 1;
    padding: 15px 20px;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 94, 0, 0.3);
    border-radius: 30px;
    color: #ffffff;
    font-size: 1rem;
    outline: none;
    transition: all 0.3s ease;
}

.newsletter-form input::placeholder {
