    padding: 0;
    margin: 0;
}

.footer-links li {
    margin-bottom: 15px;
    position: relative;
}

.footer-links a {
    color: rgba(255, 255, 255, 0.7);
    text-decoration: none;
    font-size: 0.95rem;
    font-weight: 400;
    transition: all 0.3s ease;
    position: relative;
    padding: 0;
    display: block;
    border-radius: 0;
    margin: 0;
    line-height: 1.6;
}

.footer-links a:hover {
    color: #FF5E00;
    background: none;
    padding-left: 0;
    transform: none;
}

/* Newsletter Section - Separate */
.newsletter-section {
    margin-top: 50px;
