    border: 1px solid rgba(255, 255, 255, 0.07);
}

.shop-detail-spec .spec-label {
    display: block;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: rgba(255, 255, 255, 0.6);
    margin-bottom: 6px;
}

.shop-detail-spec .spec-value {
    font-size: 0.95rem;
    color: rgba(255, 255, 255, 0.85);
    font-weight: 600;
}

.shop-detail-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 16px;
    align-items: center;
}

.shop-detail-add-cart,
.shop-detail-view-product {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 12px 24px;
    border-radius: 999px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    cursor: pointer;
    transition: all 0.3s ease;
    border: none;
    text-decoration: none;
}

.shop-detail-add-cart {
    background: linear-gradient(135deg, #FF5E00, #FF8C00);
    color: #ffffff;
}

.shop-detail-add-cart:hover {
    transform: translateY(-2px);
    box-shadow: 0 12px 24px rgba(255, 94, 0, 0.35);
}

.shop-detail-view-product {
    background: transparent;
    color: rgba(255, 255, 255, 0.8);
    border: 1px solid rgba(255, 255, 255, 0.25);
}

.shop-detail-view-product:hover {
    color: #00E5FF;
    border-color: #00E5FF;
    transform: translateY(-2px);
}

@media (max-width: 768px) {
    .shop-product-detail-inner {
        padding: 24px;
    }

    .shop-detail-actions {
        flex-direction: column;
        align-items: stretch;
    }

    .shop-detail-add-cart,
    .shop-detail-view-product {
        justify-content: center;
        width: 100%;
    }
}

.shop-product-card.selected,
.shop-products-grid .shop-product-card.selected {
    border-color: rgba(255, 94, 0, 0.75) !important;
    box-shadow: 0 0 0 2px rgba(255, 94, 0, 0.35), 0 18px 36px rgba(0, 0, 0, 0.4) !important;
}

/* Category hero alignment */
.category-hero {
    background: linear-gradient(135deg, rgba(255, 94, 0, 0.08), rgba(0, 178, 255, 0.08));
    padding: 40px 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.category-header-content {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 32px;
    flex-wrap: wrap;
}

.category-header-copy {
    max-width: 640px;
}

.category-header-meta {
    display: flex;
    gap: 16px;
    flex-wrap: wrap;
}

.category-meta-item {
    min-width: 140px;
    padding: 16px 20px;
    border-radius: 18px;
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid rgba(255, 255, 255, 0.12);
    text-align: center;
}

.category-meta-value {
    display: block;
    font-size: 1.6rem;
    font-weight: 700;
    color: #ffffff;
}

.category-meta-label {
    display: block;
    font-size: 0.85rem;
    color: rgba(255, 255, 255, 0.65);
    letter-spacing: 0.5px;
    text-transform: uppercase;
}

@media (max-width: 768px) {
    .category-header-content {
        gap: 24px;
    }

    .category-meta-item {
        min-width: calc(50% - 12px);
    }
}

.shop-empty-state {
    text-align: center;
    padding: 80px 20px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 20px;
    color: rgba(255, 255, 255, 0.75);
}

.shop-empty-state h3 {
    font-size: 1.6rem;
    margin-bottom: 12px;
    color: #ffffff;
}

.shop-empty-state p {
    margin: 0 0 20px;
}

.shop-empty-state a {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 12px 24px;
    border-radius: 999px;
    background: linear-gradient(135deg, #FF5E00, #FF8C00);
    color: #ffffff;
    text-decoration: none;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

