.recommended-products .product-card {
  max-width: 280px;
  margin: 0 auto;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.recommended-products .product-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 25px 45px rgba(12, 30, 55, 0.35);
}

.recommended-products .product-image {
  height: 190px;
}

.recommended-products .product-title {
  font-size: 1.05rem;
}

.recommended-products .product-actions .add-to-cart-btn {
  padding: 10px 14px;
  font-size: 0.85rem;
  border-radius: 12px;
}

@media (max-width: 1024px) {
  .cart-layout {
    grid-template-columns: 1fr;
  }

  .cart-summary {
    position: static;
  }
}

@media (max-width: 768px) {
  .cart-hero {
    padding: 96px 0 60px;
  }

  .cart-breadcrumb {
    flex-wrap: wrap;
    justify-content: center;
    gap: 10px;
  }

  .cart-hero-text h1 {
    font-size: 2.1rem;
  }

  .cart-content {
    padding: 72px 0 60px;
  }

  .cart-items-section,
  .summary-card {
    padding: 24px;
  }

  .cart-item-detailed {
    grid-template-columns: 100px minmax(0, 1fr);
    grid-template-rows: auto auto;
  }

  .cart-item-controls {
    grid-column: 1 / -1;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }

  .security-badges {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 576px) {
  .cart-breadcrumb {
    justify-content: flex-start;
  }

  .cart-hero-text h1 {
    font-size: 1.9rem;
  }

  .cart-item-detailed {
    grid-template-columns: 1fr;
  }

  .cart-item-controls {
    flex-direction: column;
    align-items: flex-start;
  }

  .cart-actions {
    flex-direction: column;
    gap: 16px;
  }
}

@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@400;700;900&family=Rajdhani:wght@300;400;500;700&display=swap');

@import url('https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css');

/*

TemplateMo 596 Electric Xtra

https://templatemo.com/tm-596-electric-xtra

