}

.item-details {
    flex: 1;
}

.item-details h4 {
    color: white;
    margin: 0 0 5px 0;
    font-size: 0.9rem;
    font-weight: 600;
}

.item-quantity {
    font-size: 0.8rem;
    color: rgba(255, 255, 255, 0.6);
}

.item-price {
    color: #FF5E00;
    font-weight: 700;
    font-size: 1rem;
}

.summary-totals {
    margin-top: 20px;
    padding-top: 20px;
    border-top: 1px solid rgba(255, 94, 0, 0.2);
}

.summary-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 10px;
    color: rgba(255, 255, 255, 0.8);
}

.summary-row.total {
    font-size: 1.2rem;
    font-weight: 700;
    color: #FF5E00;
    padding-top: 15px;
    border-top: 2px solid rgba(255, 94, 0, 0.3);
    margin-top: 15px;
}

.btn-checkout {
    width: 100%;
    background: linear-gradient(45deg, #FF5E00, #00B2FF);
    color: white;
    border: none;
    padding: 18px 30px;
    border-radius: 12px;
    font-size: 1.1rem;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.3s ease;
    margin-top: 20px;
}

.btn-checkout:hover {
    transform: translateY(-2px);
    box-shadow: 0 15px 35px rgba(255, 94, 0, 0.4);
}

/* Responsive Design */
@media (max-width: 768px) {
    .nav-actions {
        gap: 10px;
    }
    
    .search-box input {
        width: 150px;
    }
    
    .search-box input:focus {
        width: 180px;
    }
    
    .products-grid {
        grid-template-columns: repeat(3, 1fr);
        gap: 20px;
    }
    
    .form-row {
