    grid-template-columns: repeat(4, 1fr);
    gap: 30px;
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 20px;
}

.collection-card {
    height: 500px;
    border-radius: 20px;
    overflow: hidden;
    position: relative;
    cursor: pointer;
    transition: all 0.4s ease;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
}

.collection-card:hover {
    transform: translateY(-10px);
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.2);
}

.card-background {
    width: 100%;
    height: 100%;
    position: relative;
    overflow: hidden;
}

.card-image {
    width: 100%;
    height: 100%;
    position: absolute;
    top: 0;
    left: 0;
    z-index: 1;
}

.card-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.4s ease;
}

.collection-card:hover .card-image img {
    transform: scale(1.1);
}

.card-content {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    padding: 30px;
    background: linear-gradient(transparent, rgba(0, 0, 0, 0.8));
    color: white;
    z-index: 2;
    transform: translateY(20px);
    transition: transform 0.3s ease;
}

.collection-card:hover .card-content {
    transform: translateY(0);
}

.card-title {
    font-size: 0.9rem;
    font-weight: 600;
    margin-bottom: 8px;
    opacity: 0.9;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.card-main-title {
    font-size: 1.8rem;
    font-weight: 800;
    margin-bottom: 15px;
    text-shadow: 0 2px 4px rgba(0, 0, 0, 0.5);
    line-height: 1.2;
}

.card-price {
    font-size: 1.1rem;
    font-weight: 700;
    color: #FFD700;
    text-shadow: 0 2px 4px rgba(0, 0, 0, 0.5);
}

/* Individual Card Styles */
.bicycle-card {
    background: linear-gradient(135deg, rgba(0, 178, 255, 0.8) 0%, rgba(0, 178, 255, 0.6) 100%);
}

.cricket-card {
    background: linear-gradient(135deg, rgba(255, 94, 0, 0.8) 0%, rgba(255, 140, 66, 0.8) 100%);
}

.gym-card {
    background: linear-gradient(135deg, rgba(40, 40, 40, 0.9) 0%, rgba(60, 60, 60, 0.8) 100%);
}

.roller-card {
    background: linear-gradient(135deg, rgba(255, 94, 0, 0.9) 0%, rgba(0, 178, 255, 0.7) 100%);
}

/* Responsive Design for Explore Collection */
@media (max-width: 1200px) {
    .collection-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 25px;
    }
}

@media (max-width: 768px) {
    .explore-collection {
        padding: 60px 0;
    }
    
    .collection-title {
        font-size: 2rem;
        margin-bottom: 40px;
    }
    
