.use-category {
    display: flex;
    align-items: flex-start;
    gap: 15px;
    padding: 25px;
    background: #f8f9fa;
    border-radius: 10px;
    border: 1px solid #e9ecef;
}

.category-icon {
    width: 50px;
    height: 50px;
    background: linear-gradient(45deg, #FF5E00, #00B2FF);
    color: white;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.2rem;
    flex-shrink: 0;
}

.category-content h4 {
    margin: 0 0 8px 0;
    font-size: 1.1rem;
    font-weight: 600;
}

.category-content p {
    margin: 0;
    font-size: 0.95rem;
    color: #666;
    line-height: 1.5;
}

/* Sharing Scenarios */
.sharing-scenarios {
    margin: 30px 0;
}

.scenario-item {
    margin-bottom: 20px;
    padding: 20px;
    background: #f8f9fa;
    border-radius: 10px;
    border: 1px solid #e9ecef;
}

.scenario-item h4 {
    display: flex;
    align-items: center;
    gap: 10px;
    margin: 0 0 10px 0;
    font-size: 1.1rem;
    font-weight: 600;
}

.scenario-item i {
    color: #FF5E00;
}

.scenario-item p {
    margin: 0;
    font-size: 0.95rem;
    color: #666;
    line-height: 1.5;
}

/* Security Measures */
.security-measures {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 20px;
    margin: 30px 0;
}

.security-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 20px;
    background: #d4edda;
    border-radius: 10px;
    border: 1px solid #c3e6cb;
    text-align: center;
}

.security-item i {
    color: #155724;
    font-size: 1.5rem;
    margin-bottom: 10px;
}

.security-item span {
    color: #155724;
    font-weight: 600;
    font-size: 0.95rem;
}

/* Cookie Types */
.cookie-types {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 20px;
    margin: 30px 0;
}

.cookie-type {
    padding: 20px;
    background: #f8f9fa;
    border-radius: 10px;
    border: 1px solid #e9ecef;
}

.cookie-type h4 {
    margin: 0 0 10px 0;
    font-size: 1.1rem;
    font-weight: 600;
    color: #333;
}

.cookie-type p {
    margin: 0;
    font-size: 0.95rem;
    color: #666;
    line-height: 1.5;
}

/* Rights Grid */
.rights-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 20px;
    margin: 30px 0;
}

.right-item {
    text-align: center;
    padding: 25px;
    background: #f8f9fa;
    border-radius: 10px;
    border: 1px solid #e9ecef;
    transition: all 0.3s ease;
}

.right-item:hover {
    background: white;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
    border-color: #FF5E00;
}

.right-item i {
    color: #FF5E00;
    font-size: 2rem;
    margin-bottom: 15px;
}

.right-item h4 {
    margin: 0 0 10px 0;
    font-size: 1.1rem;
    font-weight: 600;
}

.right-item p {
    margin: 0;
    font-size: 0.95rem;
    color: #666;
}

/* Contact Info */
.contact-info {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 20px;
    margin: 30px 0;
}

.contact-method {
    display: flex;
    align-items: flex-start;
    gap: 15px;
    padding: 20px;
    background: #f8f9fa;
    border-radius: 10px;
    border: 1px solid #e9ecef;
}

.contact-method i {
    color: #FF5E00;
    font-size: 1.3rem;
    margin-top: 2px;
}

.contact-method h4 {
    margin: 0 0 5px 0;
    font-size: 1.1rem;
    font-weight: 600;
    color: #000!important;
}

.contact-method p {
    margin: 0;
    font-size: 0.95rem;
    color: #666!important;
}

/* Responsive Design */
@media (max-width: 1024px) {
    .policy-wrapper {
        grid-template-columns: 1fr;
        gap: 30px;
    }
    
    .policy-sidebar {
        position: static;
    }
    
    .usage-guidelines,
    .order-terms,
    .return-policy,
    .prohibited-list,
    .liability-disclaimer,
    .legal-info {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 768px) {
    .policy-hero {
        padding: 60px 0 40px;
    }
    
    .policy-title {
        font-size: 2.5rem;
    }
    
    .policy-subtitle {
        font-size: 1.1rem;
    }
    
    .policy-meta {
        flex-direction: column;
        gap: 15px;
    }
    
    .policy-main {
        padding: 25px;
    }
    
    .policy-section h2 {
        font-size: 1.8rem;
    }
    
    .claim-steps {
        margin: 20px 0;
    }
    
    .step-item {
        flex-direction: column;
        text-align: center;
    }
    
    .repair-options,
    .extended-warranty-plans {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 480px) {
    .policy-title {
        font-size: 2rem;
    }
    
    .policy-main {
        padding: 20px;
    }
    
    .policy-section h2 {
        font-size: 1.5rem;
    }
    
    .warranty-periods,
    .coverage-grid,
    .support-channels {
        grid-template-columns: 1fr;
    }
}